import pytest

from inline_snapshot import Is
from inline_snapshot.testing import Example


@pytest.mark.parametrize(
    "storage_class, actual",
    [
        ("LegacyStorage", "stored"),
        ("DefaultStorage", "stored"),
        ("CustomStorage", "STORED"),
    ],
)
def test_storage_comparison(storage_class, actual):
    Example(
        {
            "stored.txt": "stored",
            "conftest.py": f"""\
from contextlib import contextmanager
from pathlib import Path

from inline_snapshot import register_format
from inline_snapshot._core._external._format._text import TextFormat
from inline_snapshot.plugin import StorageLookupError
from inline_snapshot.plugin import Storage
from inline_snapshot.plugin import hookimpl

@register_format(replace_handler=True)
class ReadOnlyFormat(TextFormat):
    def encode(self, value, path):
        raise AssertionError("comparison must not serialize the value")

class LegacyStorage(Storage):
    def find_unused_externals(self, used_externals):
        return []

    def check_externals(self, used_externals):
        pass

    @contextmanager
    def load(self, location):
        assert location.storage == "custom"
        if location.stem == "missing":
            raise StorageLookupError("missing snapshot", files=[])
        assert location.stem == "value"
        yield Path("stored.txt")

class DefaultStorage(LegacyStorage, Storage):
    pass

class CustomStorage(DefaultStorage):
    def lazy_compare(self, location, other):
        with self.load(location) as path:
            return path.read_text().casefold() == other.value.casefold()

@hookimpl
def register_storages(storage_dir):
    return {{"custom": {storage_class}()}}
""",
            "tests/test_something.py": f"""\
from inline_snapshot import external, get_snapshot_value
from inline_snapshot._core._global_state import state

def test_value():
    expected = external("custom:value.txt")
    assert expected == {actual!r}
    assert {actual!r} == expected
    assert not (expected != {actual!r})
    if not state().active:
        assert get_snapshot_value(expected) == "stored"
        if {storage_class!r} != "CustomStorage":
            assert isinstance(expected, str)
        else:
            assert repr(expected) == 'external("custom:value.txt")'
            assert expected != "different"
            assert "different" != expected
            assert get_snapshot_value(external("custom:missing.txt")) is ...
            assert state().snapshots == {{}}
            assert state().incorrect_values == 0
            assert state().missing_values == 0
""",
        }
    ).run_inline(
        changed_files={
            ".inline-snapshot/files_using_external.txt": """\
# this file is generated by inline-snapshot and requires no manual edits (https://15r10nk.github.io/inline-snapshot/latest/external/external/#cleaning-up-old-externals)
tests/test_something.py
""",
        }
    ).run_pytest(
        ["--inline-snapshot=disable"], outcomes={"passed": 1}, changed_files={}
    )


@pytest.mark.parametrize(
    "comparison, actual",
    [
        ("shortcut", "stored"),
        ("data", "stored"),
        ("data", "changed"),
    ],
)
@pytest.mark.parametrize("disabled", [False, True])
def test_lazy_serialization(comparison, actual, disabled):
    changed_files = {
        ".inline-snapshot/files_using_external.txt": """\
# this file is generated by inline-snapshot and requires no manual edits (https://15r10nk.github.io/inline-snapshot/latest/external/external/#cleaning-up-old-externals)
tests/test_something.py
""",
    }
    if disabled:
        changed_files = {}
    elif actual == "changed":
        changed_files["stored.txt"] = actual

    Example(
        {
            "stored.txt": "stored",
            "conftest.py": f"""\
from contextlib import contextmanager
from pathlib import Path

from inline_snapshot import register_format
from inline_snapshot._core._external._format._text import TextFormat
from inline_snapshot.plugin import Storage, StorageValue, hookimpl

encoded_paths = []

@register_format(replace_handler=True)
class CountingFormat(TextFormat):
    def encode(self, value, path):
        encoded_paths.append(path)
        super().encode(value, path)

class CustomStorage(Storage):
    @contextmanager
    def load(self, location):
        assert {actual!r} == "changed"
        yield Path("stored.txt")

    def lazy_compare(self, location, other: StorageValue):
        assert other.value == {actual!r}
        assert encoded_paths == []
        if {comparison!r} == "shortcut":
            return other.value == "stored"
        self.compared_path = other.data
        assert isinstance(other.data, Path)
        assert other.data is self.compared_path
        assert encoded_paths == [self.compared_path]
        return other.data.read_text() == "stored"

    def new_location(self, location, file_path):
        assert file_path == self.compared_path
        assert encoded_paths == [file_path], "update must reuse serialized data"
        return location

    def store(self, location, file_path):
        assert file_path == self.compared_path
        assert encoded_paths == [file_path]
        Path("stored.txt").write_bytes(file_path.read_bytes())

    def find_unused_externals(self, used_externals):
        return []

    def check_externals(self, used_externals):
        assert len(encoded_paths) == (1 if {comparison!r} == "data" else 0)

@hookimpl
def register_storages():
    return {{"custom": CustomStorage()}}
""",
            "tests/test_something.py": f"""\
from inline_snapshot import external

def test_value():
    assert (external("custom:value.txt") == {actual!r}) is {not (disabled and actual == "changed")!r}
""",
        }
    ).run_inline(
        ["--inline-snapshot=disable" if disabled else "--inline-snapshot=fix"],
        reported_categories=Is(
            {"fix"} if actual == "changed" and not disabled else set()
        ),
        changed_files=Is(changed_files),
    )


def test_external_comparisons_are_rejected():
    Example(
        {
            "conftest.py": """\
from inline_snapshot.plugin import Storage, hookimpl

class CustomStorage(Storage):
    def lazy_compare(self, location, other):
        raise AssertionError("external comparisons must not reach the backend")

@hookimpl
def register_storages():
    return {"custom": CustomStorage()}
""",
            "tests/test_something.py": """\
import pytest

from inline_snapshot import UsageError, external
from inline_snapshot._core._global_state import state

def test_comparison():
    active = external("custom:value.txt")
    state().active = False
    try:
        inactive = external("custom:value.txt")
    finally:
        state().active = True

    for left, right in [(active, active), (inactive, inactive), (active, inactive), (inactive, active)]:
        with pytest.raises(UsageError, match="you cannot compare external"):
            left == right
    assert state().missing_values == 0
    assert state().incorrect_values == 0
""",
        }
    ).run_inline(
        changed_files={
            ".inline-snapshot/files_using_external.txt": """\
# this file is generated by inline-snapshot and requires no manual edits (https://15r10nk.github.io/inline-snapshot/latest/external/external/#cleaning-up-old-externals)
tests/test_something.py
""",
        }
    )
